# Simpler approach: each pattern fills all diagonals from it
rows, cols = 13, 23
grid = [[2] * cols for _ in range(rows)]

patterns = [
    ((2,14), 8),
    ((2,17), 7),
    ((3,15), 7),
    ((3,16), 7),
    ((4,15), 5),
    ((4,16), 3),
    ((5,14), 5),
]

pattern_set = set((p[0], p[1]) for p in patterns)

for (pr, pc), val in patterns:
    # Fill NW direction: r decreases, c decreases
    for r in range(pr - 1, -1, -1):
        c = r - (pr - pc)  # r-c = pr-pc
        if 0 <= c < cols:
            grid[r][c] = val

    # Fill SE direction: r increases, c increases
    for r in range(pr + 1, rows):
        c = r - (pr - pc)  # r-c = pr-pc
        if 0 <= c < cols:
            grid[r][c] = val

    # Fill NE direction: r decreases, c increases
    for r in range(pr - 1, -1, -1):
        c = (pr + pc) - r  # r+c = pr+pc
        if 0 <= c < cols:
            grid[r][c] = val

    # Fill SW direction: r increases, c decreases
    for r in range(pr + 1, rows):
        c = (pr + pc) - r  # r+c = pr+pc
        if 0 <= c < cols:
            grid[r][c] = val

# Set pattern cells themselves
for (pr, pc), val in patterns:
    grid[pr][pc] = val

for i, row in enumerate(grid):
    print(f"Row {i}: {row}")

